import { execSync } from "node:child_process";
import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

export async function cdc_row_count_matches_source(ctx: AssertionContext): Promise<AssertionResult> {
  const pgResult = await ctx.pg.query("SELECT count(*) AS n FROM app.orders");
  const sourceCount = Number(pgResult.rows[0]?.n ?? 0);

  const broker = ctx.env("REDPANDA_BROKER") ?? "localhost:9092";
  let topicCount = 0;
  try {
    const out = execSync(
      `python3 -c "
from kafka import KafkaConsumer
c = KafkaConsumer('orders', bootstrap_servers=['${broker}'], auto_offset_reset='earliest', consumer_timeout_ms=3000)
topicCount = sum(1 for _ in c)
c.close()
print(topicCount)
"`,
      { encoding: "utf8", timeout: 5000 },
    );
    topicCount = parseInt(out.trim(), 10) || 0;
  } catch {
    topicCount = 0;
  }

  const passed = topicCount >= sourceCount;
  return {
    passed,
    message: passed
      ? `CDC row count matches: source=${sourceCount}, topic=${topicCount}.`
      : `Source ${sourceCount}, topic ${topicCount}.`,
    details: { sourceCount, topicCount },
  };
}

import { execSync } from "node:child_process";
import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

function getMessageCount(ctx: AssertionContext): number {
  const broker = ctx.env("REDPANDA_BROKER") ?? "localhost:9092";
  try {
    const out = execSync(
      `python3 -c "
from kafka import KafkaConsumer
c = KafkaConsumer('orders', bootstrap_servers=['${broker}'], auto_offset_reset='earliest', consumer_timeout_ms=3000)
count = sum(1 for _ in c)
c.close()
print(count)
"`,
      { encoding: "utf8", timeout: 5000 },
    );
    return parseInt(out.trim(), 10) || 0;
  } catch {
    return 0;
  }
}

export async function orders_topic_has_messages(ctx: AssertionContext): Promise<AssertionResult> {
  const count = getMessageCount(ctx);
  const passed = count >= 10;
  return {
    passed,
    message: passed ? `Orders topic has ${count} messages.` : `Expected >=10 messages, got ${count}.`,
    details: { count },
  };
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

import { avoidsSelectStarQueries, scanWorkspaceForHardcodedConnections } from "../../_shared/assertion-helpers";

export async function no_hardcoded_credentials(ctx: AssertionContext): Promise<AssertionResult> {
  const { readdirSync, readFileSync } = await import("node:fs");
  const { join } = await import("node:path");
  const dirs = ["/workspace"];
  const suspectPatterns = ["password", "secret", "5432"];
  let found = "";
  for (const dir of dirs) {
    try {
      for (const f of readdirSync(dir)) {
        if (!/\.(py|js|ts|json)$/.test(f)) continue;
        const content = readFileSync(join(dir, f), "utf8");
        for (const p of suspectPatterns) {
          if (content.includes(p) && !content.includes("process.env") && !content.includes("os.environ")) {
            found = join(dir, f);
            break;
          }
        }
      }
    } catch {
      continue;
    }
  }
  return {
    passed: !found,
    message: found ? `Hardcoded credentials in ${found}.` : "No hardcoded credentials.",
    details: found ? { found } : undefined,
  };
}

